import { useState, useEffect, useRef, useCallback } from 'react';

interface ChainHeadState {
  blockNumber: number | null;
  loading: boolean;
  error: string | null;
}

export function useChainHead(rpcUrl: string): ChainHeadState {
  const [state, setState] = useState<ChainHeadState>({
    blockNumber: null,
    loading: true,
    error: null,
  });

  const isMountedRef = useRef<boolean>(true);
  const abortControllerRef = useRef<AbortController | null>(null);

  const fetchBlockNumber = useCallback(async () => {
    if (!isMountedRef.current) return;

    // Cancel any pending request
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }

    const controller = new AbortController();
    abortControllerRef.current = controller;

    try {
      const response = await fetch(rpcUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          jsonrpc: '2.0',
          id: 1,
          method: 'eth_blockNumber',
          params: [],
        }),
        signal: controller.signal,
      });

      if (!isMountedRef.current) return;

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();

      if (!isMountedRef.current) return;

      if (data.error) {
        throw new Error(data.error.message || 'RPC error');
      }

      const hexBlockNumber = data.result as string;
      const blockNumber = parseInt(hexBlockNumber, 16);

      if (isNaN(blockNumber)) {
        throw new Error('Invalid block number format');
      }

      setState({
        blockNumber,
        loading: false,
        error: null,
      });
    } catch (err: unknown) {
      if (!isMountedRef.current) return;

      // Ignore abort errors
      if (err instanceof Error && err.name === 'AbortError') {
        return;
      }

      const errorMessage = err instanceof Error ? err.message : 'Unknown error';
      setState({
        blockNumber: null,
        loading: false,
        error: errorMessage,
      });
    }
  }, [rpcUrl]);

  useEffect(() => {
    isMountedRef.current = true;

    // Initial fetch
    fetchBlockNumber();

    // Set up interval
    const intervalId = setInterval(() => {
      fetchBlockNumber();
    }, 5000);

    return () => {
      isMountedRef.current = false;
      clearInterval(intervalId);
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
    };
  }, [fetchBlockNumber]);

  return state;
}
